function renderCalculator(body){body.innerHTML=`<div class="calc"><p class="eyebrow">UTILITY</p><h2 class="app-title">Calculator</h2><div class="calc-history" id="calcHistory">${esc(state.calcPrev)}</div><div class="calc-display" id="calcDisplay">${esc(state.calc)}</div><div class="calc-grid">${['AC','±','%','÷','7','8','9','×','4','5','6','−','1','2','3','+','⌫','0','.','='].map(x=>`<button class="${['÷','×','−','+','%'].includes(x)?'operator':''} ${x==='='?'equals':''}" data-calc="${x}">${x}</button>`).join('')}</div><p class="app-subtitle" style="text-align:center;margin-top:12px">Keyboard input supported · division by zero is handled safely</p></div>`;body.querySelectorAll('[data-calc]').forEach(b=>b.onclick=()=>calcInput(b.dataset.calc,body))}
function calcInput(k,body){let v=state.calc;if(k==='AC'){v='0';state.calcPrev=''}else if(k==='⌫')v=v.length>1?v.slice(0,-1):'0';else if(k==='±')v=v.startsWith('-')?v.slice(1):'-'+v;else if(k==='='){try{const expression=v.replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-');if(!/^[\d.+\-*/()%\s]+$/.test(expression))throw 0;const tokens=expression.match(/\d+(?:\.\d+)?|[()+\-*/%]/g)||[];const result=safeMath(tokens);if(!Number.isFinite(result))throw 0;state.calcPrev=v+' =';v=String(Number(result.toFixed(10)))}catch{state.calcPrev='Invalid expression';v='Error'}}else if(v==='Error')v=k.match(/[0-9.]/)?k:'0'+k;else if(['+','−','×','÷','%'].includes(k)){if(/[+−×÷%]$/.test(v))v=v.slice(0,-1)+k;else v+=k}else v=v==='0'&&k!=='.'?k:v+k;state.calc=v;$('#calcDisplay',body).textContent=v;$('#calcHistory',body).textContent=state.calcPrev}
