function renderMusic(body){body.innerHTML=`<p class="eyebrow">WAVE · LOCAL PLAYER</p><h2 class="app-title">Soundtrack your focus.</h2><p class="app-subtitle">Choose audio files from your device. No songs are bundled or streamed by NOVA.</p><div class="app-toolbar"><input type="file" id="audioPick" accept="audio/*" multiple class="field" style="flex:1"><button id="audioClear">Clear queue</button></div><div id="audioList" class="empty-state"><strong>Your library starts here.</strong><span>Import audio to build a local queue.</span></div><audio id="waveAudio" controls style="width:100%;margin-top:15px"></audio><p id="waveStatus" class="saved-label">Nothing playing</p>`;let tracks=[];const list=$('#audioList',body),audio=$('#waveAudio',body);$('#audioPick',body).onchange=e=>{tracks.push(...[...e.target.files].map(f=>({name:f.name,file:f,url:URL.createObjectURL(f)})));list.className='';list.innerHTML=tracks.map((t,i)=>`<button class="settings-row" data-track="${i}" style="width:100%;text-align:left;background:transparent;color:var(--text);border-left:0;border-right:0"><span>♫ ${esc(t.name)}<small>${formatBytes(t.file.size)}</small></span><span>Play ↗</span></button>`).join('');list.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>{const t=tracks[+b.dataset.track];audio.src=t.url;audio.play().then(()=>$('#waveStatus',body).textContent='Playing · '+t.name).catch(()=>toast('Playback requires a user action.'))})};$('#audioClear',body).onclick=()=>{audio.pause();tracks.forEach(t=>URL.revokeObjectURL(t.url));tracks=[];list.className='empty-state';list.innerHTML='<strong>Your library starts here.</strong><span>Import audio to build a local queue.</span>';audio.removeAttribute('src');$('#waveStatus',body).textContent='Nothing playing'}}
function renderGames(body){body.innerHTML=`<p class="eyebrow">ARCADE</p><h2 class="app-title">A small break.</h2><p class="app-subtitle">Lightweight games run locally in this window.</p><div class="app-toolbar"><button class="primary" data-game="2048">Play 2048</button><button data-game="memory">Memory Match</button><button data-game="snake">Snake</button></div><div id="gameArea" class="empty-state"><strong>Choose a game</strong><span>Keyboard and touch controls are supported where practical.</span></div>`;body.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>{if(b.dataset.game==='2048')game2048($('#gameArea',body));else if(b.dataset.game==='memory')gameMemory($('#gameArea',body));else gameSnake($('#gameArea',body))})}
function game2048(root){let grid=Array.from({length:4},()=>Array(4).fill(0)),score=0;function add(){const empty=[];grid.forEach((r,y)=>r.forEach((v,x)=>{if(!v)empty.push([x,y])}));if(empty.length){const [x,y]=empty[Math.floor(Math.random()*empty.length)];grid[y][x]=Math.random()<.9?2:4}}function draw(){root.className='';root.innerHTML=`<div style="display:flex;justify-content:space-between;align-items:center"><b>2048</b><span>Score ${score}</span><button class="app-button" id="gReset">Restart</button></div><div class="game-board" style="grid-template-columns:repeat(4,1fr)">${grid.flat().map(v=>`<div class="game-cell ${v?'filled v'+Math.min(v,8):''}">${v||''}</div>`).join('')}</div><p class="game-hint">Arrow keys / WASD or swipe. Merge equal tiles.</p>`;$('#gReset',root).onclick=()=>game2048(root)}function move(dir){let changed=false;for(let i=0;i<4;i++){let line=dir==='left'||dir==='right'?grid[i].slice():grid.map(r=>r[i]);if(dir==='right'||dir==='down')line.reverse();let a=line.filter(Boolean),n=[];for(let j=0;j<a.length;j++){if(a[j]===a[j+1]){n.push(a[j]*2);score+=a[j]*2;j++}else n.push(a[j])}while(n.length<4)n.push(0);if(dir==='right'||dir==='down')n.reverse();for(let j=0;j<4;j++){const x=dir==='left'||dir==='right'?j:i,y=dir==='left'||dir==='right'?i:j,v=n[j];if(grid[y][x]!==v)changed=true;grid[y][x]=v}}if(changed){add();draw()}}add();add();draw();root.tabIndex=0;root.onkeydown=e=>{const m={ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right',ArrowUp:'up',w:'up',ArrowDown:'down',s:'down'};if(m[e.key]){e.preventDefault();move(m[e.key])}};let sx=0,sy=0;root.ontouchstart=e=>{sx=e.touches[0].clientX;sy=e.touches[0].clientY};root.ontouchend=e=>{const dx=e.changedTouches[0].clientX-sx,dy=e.changedTouches[0].clientY-sy;if(Math.max(Math.abs(dx),Math.abs(dy))>25)move(Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up')}}
function gameMemory(root){const vals=['◆','●','▲','★','✦','⬟','☾','♥'];let cards=[...vals,...vals].sort(()=>Math.random()-.5),opened=[],matched=new Set(),moves=0;function draw(){root.className='';root.innerHTML=`<div style="display:flex;justify-content:space-between"><b>Memory Match</b><span>Moves ${moves}</span><button class="app-button" id="memReset">Restart</button></div><div class="game-board" style="grid-template-columns:repeat(4,1fr)">${cards.map((v,i)=>`<button class="game-cell ${matched.has(i)?'filled':''}" data-card="${i}">${matched.has(i)||opened.includes(i)?v:'?'}</button>`).join('')}</div><p class="game-hint">Find all matching pairs.</p>`;root.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>{const i=+b.dataset.card;if(matched.has(i)||opened.includes(i)||opened.length===2)return;opened.push(i);if(opened.length===2){moves++;if(cards[opened[0]]===cards[opened[1]]){opened.forEach(j=>matched.add(j));opened=[];if(matched.size===cards.length)toast('Memory Match complete!')}else setTimeout(()=>{opened=[];draw()},650)}draw()});$('#memReset',root).onclick=()=>gameMemory(root)}draw()}
function gameSnake(root){root.className='';root.innerHTML=`<b>Snake</b><p class="game-hint">Use arrow keys or WASD. Eat the dot to grow.</p><canvas id="snakeCanvas" width="320" height="320" style="display:block;width:min(100%,320px);margin:12px auto;border:1px solid var(--line);border-radius:8px;background:#0c1217"></canvas><div class="game-actions"><button class="app-button" id="snakeStart">Start / Restart</button><span id="snakeScore">Score 0</span></div>`;const c=$('#snakeCanvas',root),ctx=c.getContext('2d');let snake,food,dir,run=false,score=0,timer;function reset(){snake=[[8,8],[7,8],[6,8]];food=[12,10];dir=[1,0];score=0;run=true;clearInterval(timer);timer=setInterval(tick,130);draw()}function draw(){ctx.clearRect(0,0,320,320);ctx.fillStyle='#a8e2d1';snake.forEach(([x,y])=>ctx.fillRect(x*20+2,y*20+2,16,16));ctx.fillStyle='#e8a47e';ctx.beginPath();ctx.arc(food[0]*20+10,food[1]*20+10,7,0,Math.PI*2);ctx.fill();$('#snakeScore',root).textContent='Score '+score}function tick(){if(!run)return;const h=[snake[0][0]+dir[0],snake[0][1]+dir[1]];if(h[0]<0||h[0]>15||h[1]<0||h[1]>15||snake.some(([x,y])=>x===h[0]&&y===h[1])){run=false;clearInterval(timer);toast('Snake game over · Score '+score);return}snake.unshift(h);if(h[0]===food[0]&&h[1]===food[1]){score++;food=[Math.floor(Math.random()*16),Math.floor(Math.random()*16)]}else snake.pop();draw()}root.tabIndex=0;root.onkeydown=e=>{const d={ArrowLeft:[-1,0],a:[-1,0],ArrowRight:[1,0],d:[1,0],ArrowUp:[0,-1],w:[0,-1],ArrowDown:[0,1],s:[0,1]}[e.key];if(d&&d[0]!==-dir[0]&&d[1]!==-dir[1]){e.preventDefault();dir=d}};$('#snakeStart',root).onclick=reset;reset()}
function renderCalendar(body){const now=new Date();body.innerHTML=`<p class="eyebrow">YOUR TIME</p><h2 class="app-title">Calendar</h2><p class="app-subtitle">Events are saved locally in this browser.</p><div class="app-toolbar"><button id="calPrev">←</button><b id="calMonth" style="flex:1;text-align:center"></b><button id="calNext">→</button><button class="primary" id="calAdd">＋ Event</button></div><div id="calGrid" style="display:grid;grid-template-columns:repeat(7,1fr);gap:5px"></div><h3 style="font-size:14px;margin-top:20px">Upcoming events</h3><div id="eventList"></div>`;let month=new Date(now.getFullYear(),now.getMonth(),1);function draw(){const m=$('#calMonth',body),grid=$('#calGrid',body);m.textContent=month.toLocaleDateString('en-US',{month:'long',year:'numeric'});const first=month.getDay(),days=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();grid.innerHTML=['S','M','T','W','T','F','S'].map(x=>`<div style="text-align:center;color:var(--muted);font-size:10px;padding:6px">${x}</div>`).join('');for(let i=0;i<first;i++)grid.innerHTML+='<span></span>';for(let d=1;d<=days;d++){const date=new Date(month.getFullYear(),month.getMonth(),d).toISOString().slice(0,10),has=state.events.some(e=>e.date===date);grid.innerHTML+=`<button data-date="${date}" style="aspect-ratio:1;border:1px solid ${date===now.toISOString().slice(0,10)?'var(--accent)':'var(--line)'};border-radius:7px;background:${has?'#a8e2d11c':'#ffffff04'};color:var(--text);font-size:11px">${d}${has?'·':''}</button>`}grid.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{const day=state.events.filter(e=>e.date===b.dataset.date);showDialog(b.dataset.date,day.map(e=>e.title+' · '+(e.time||'')).join('\n')||'No events on this date.',[['Add event',()=>addEvent(b.dataset.date,draw)],['Close',()=>{}]])});$('#eventList',body).innerHTML=state.events.slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map((e,i)=>`<div class="settings-row"><span>${esc(e.title)}<small>${e.date} ${esc(e.time||'')}</small></span><button class="app-button" data-del-event="${i}">Delete</button></div>`).join('')||'<p class="app-subtitle">No events yet.</p>';body.querySelectorAll('[data-del-event]').forEach(b=>b.onclick=()=>{state.events.splice(+b.dataset.delEvent,1);save('events',state.events);draw()})}function addEvent(date,cb){showDialog('New event','Add an event to your local NOVA calendar.',[['Save',title=>{title=String(title||'').trim();if(!title)return false;state.events.push({title,date,time:'',created:Date.now()});save('events',state.events);cb()}],['Cancel',()=>{}]],{input:'Untitled event',inputLabel:'Event title'})}$('#calPrev',body).onclick=()=>{month.setMonth(month.getMonth()-1);draw()};$('#calNext',body).onclick=()=>{month.setMonth(month.getMonth()+1);draw()};$('#calAdd',body).onclick=()=>addEvent(now.toISOString().slice(0,10),draw);draw()}
function renderClock(body){body.innerHTML=`<p class="eyebrow">UTILITY</p><h2 class="app-title">Clock</h2><div style="font-size:42px;letter-spacing:-.06em;margin:18px 0" id="clockBig">${new Date().toLocaleTimeString()}</div><p class="app-subtitle">Local device time · updates while this window is open.</p><div class="app-toolbar"><button id="swStart" class="primary">Start stopwatch</button><button id="swReset">Reset</button></div><div id="swTime" style="font-size:24px;margin:15px 0">00:00.0</div><div class="app-toolbar"><input class="field" id="timerSeconds" type="number" min="1" max="86400" value="60" style="width:100px"><button id="timerStart" class="primary">Start timer</button><button id="timerStop">Stop</button></div><p id="timerStatus" class="saved-label">Timer idle</p>`;let sw=0,base=0,swRun=false,iv;const tick=()=>{$('#clockBig',body).textContent=new Date().toLocaleTimeString();if(swRun){sw=Date.now()-base;$('#swTime',body).textContent=(sw/60000|0).toString().padStart(2,'0')+':'+((sw/1000|0)%60).toString().padStart(2,'0')+'.'+(sw%1000/100|0)}};iv=setInterval(tick,100);$('#swStart',body).onclick=()=>{swRun=!swRun;if(swRun)base=Date.now()-sw;else sw=Date.now()-base;$('#swStart',body).textContent=swRun?'Pause stopwatch':'Resume stopwatch'};$('#swReset',body).onclick=()=>{sw=0;base=Date.now();swRun=false;$('#swTime',body).textContent='00:00.0';$('#swStart',body).textContent='Start stopwatch'};let timeout;$('#timerStart',body).onclick=()=>{clearTimeout(timeout);const secs=Math.max(1,Math.min(86400,Number($('#timerSeconds',body).value)||60));$('#timerStatus',body).textContent='Timer running · '+secs+'s';timeout=setTimeout(()=>{$('#timerStatus',body).textContent='Timer finished';toast('Clock timer finished.');},secs*1000)};$('#timerStop',body).onclick=()=>{clearTimeout(timeout);$('#timerStatus',body).textContent='Timer stopped'};const obs=new MutationObserver(()=>{if(!body.isConnected){clearInterval(iv);clearTimeout(timeout);obs.disconnect()}});obs.observe(document.body,{childList:true,subtree:true})}
// Global interactions and keyboard shortcuts.
document.addEventListener('keydown',e=>{const typing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if(e.key==='Escape'){$('#contextMenu').classList.add('hidden');$('#launcher').classList.add('hidden');$('#quickPanel').classList.add('hidden');if(!$('#dialogLayer').classList.contains('hidden'))$('#dialogLayer').classList.add('hidden')}if(typing)return;if(e.ctrlKey&&e.code==='Space'){e.preventDefault();toggleLauncher()}if(e.ctrlKey&&e.shiftKey&&e.key.toLowerCase()==='t'){e.preventDefault();openApp('terminal')}if(e.ctrlKey&&e.shiftKey&&e.key.toLowerCase()==='e'){e.preventDefault();openApp('files')}if(e.ctrlKey&&e.key===','){e.preventDefault();openApp('settings')}if(e.altKey&&e.key==='F4'){e.preventDefault();const w=state.windows.find(x=>x.id===state.active);if(w){state.windows=state.windows.filter(x=>x.id!==w.id);state.active=state.windows.at(-1)?.id||null;renderWindows();renderDock()}}});
window.addEventListener('resize',()=>{state.windows.forEach(w=>{w.x=Math.max(0,Math.min(innerWidth-160,w.x));w.y=Math.max(0,Math.min(innerHeight-100,w.y))});renderWindows()});
// Fix app body interactions and make desktop right-click menu close predictably.
initState();applySettings();boot();
